def add(sid,src,quote,note,cat=None,sub='',level='Explicit'):
 assert quote in text(src),(src,quote)
 assert '\ufffd' not in quote
 eid=f'ae_b08_{sid}_{sum(e["school_id"]==sid for e in evidence)+1:02d}'
 evidence.append(dict(evidence_id=eid,school_id=sid,source_url=urls[src],page_title=title(src),accessed_date=DATE,quoted_text=quote,evidence_type='School website self-description',interpretation_note=note))
 if cat:codes.append(dict(code_id=f'ac_b08_{sid}_{sum(c["school_id"]==sid for c in codes)+1:02d}',school_id=sid,category=cat,subcategory=sub,coding_level=level,confidence='High' if level=='Explicit' else 'Medium',evidence_id=eid,coder_note='Assistant contextual review, codebook v1, coding date2026-10-28. '+note+' Public claim, not independently verified practice.',review_status='Reviewed'))
add('19377571','karlberg','Vi har ett väl inarbetat arbetssätt med bildstöd under hela skoldagen. I klassrummen finns skärmar och andra hjälpmedel utifrån elevernas behov. Eleverna får ofta arbeta i halvklass eller i mindre grupper.','Karlbergs F–3 Norrbackagatan31–33, stored official grades1–3 omit F. Multiple concrete accessible-learning practices plus six-Hjärtan framework support inclusion emphasis. Not a resource-school designation or diagnosis inference; grouping/class-count website claims not official class-size statistics.','Support, inclusion, or wellbeing emphasis','Daylong visual supports and accessible learning','Supported')
add('19593535','jensen','Vår skola präglas av studier i fokus, trygghet och studiero och vi har en tydlig hälsoprofil.','Unit-specific 4–9 page explicitly health profile; registered URL redirects to4–9 beside separate F–3 unit. Linked provider health page specifies pedagogical walks, mental-training sessions and movement several times weekly; provider detail context not independently measured at this unit. No outdoor code from nearby Mälaren or Svanen building label; no quality/effect inference.','Support, inclusion, or wellbeing emphasis','Stated health profile; movement and recovery context')
s=text('jensen_health');start=s.index('Vi går därför');end=s.index('Pedagogiska promenader',start)
add('19593535','jensen_health',s[start:end].strip(),'Provider-level health-model explanation linked/applied by unit page. Additional support for health code, not duplicate classification. Do not promote scientific/effectiveness marketing claims to verified outcomes.')
add('19657993','fryshuset_passions','När du söker till skolan väljer du en av våra passioner; Basket, bild & form, dans, musik, skate och träning & hälsa. Två gånger i veckan utövar du ditt passionsämne under skoltid.','Hammarby Sjöstad7–9 exact official unit/name/form; not Akalla/Husby. Arts code applies only to pupils choosing bild/form, dance or music; sports choices separate. Two sessions weekly stated, duration unspecified; no claim every pupil studies arts.','Arts and creative learning','Optional visual art, dance or music passion pathway')
add('19657993','fryshuset_passions','När du söker till skolan väljer du en av våra passioner; Basket, bild & form, dans, musik, skate och träning & hälsa. Två gånger i veckan utövar du ditt passionsämne under skoltid.','Same7–9 pathway evidence; this code only basket/skate/training-health choices, not every pupil. Selection choice does not establish health effect or academic outcomes.','Other stated profile','Optional basketball, skate or training/health passion pathway')
add('19657993','fryshuset_alis','ALIS är ett program i samverkan med Familjeakademin. Vi träffar er föräldrar under fyra tillfällen under årskurs 7 samt två tillfällen under åk 8 för att samtala om ledarskap i skola och i hem.','Named unit-applied active-leadership/home-school programme, meeting scope explicitly parents years7–8. Outcomes/research claims and parent testimonials excluded from project conclusions; not a verified wellbeing effect.','Support, inclusion, or wellbeing emphasis','ALIS active leadership and home-school cooperation')
add('19704413','akerstorp_goals','Studiero är ett av skolans fokusområden och vi använder oss av ”PAX i skolan”, som är en uppsättning verktyg som syftar till att skapa undervisning präglat av lugn, trygghet, glädje och studiero, samtidigt som elever får öva på självreglering, ansvarstagande och social problemlösning.','Åkerstorpsskolan F–3, official grades1–3; substantive named programme under unit goals. Page says teachers certified OR on way, with psychologist coaching; do not claim all certified or independently validate effect. Generic about page alone would not justify code.','Support, inclusion, or wellbeing emphasis','PAX classroom tools and self-regulation')
add('19733028','oden','Vi arbetar ämnesintegrerat och väver ihop flera ämnen i ett gemensamt uppdrag.','Oden F–5 Eddavägen1 matches fresh official ID19733028. Unit explicitly applies Lärandemodellen. Detailed Miljöakuten daily schedule is illustrative, not observation or proof delivered. Linked model describes recurring six periods and planned subject-integrated assignments with knowledge seeking/recipient; supports project/inquiry interpretation, not all-subject all-day project claim.','Project- or inquiry-based learning','Lärandemodellen recurring integrated assignments','Supported')
add('19733028','oden_model','Genom att samla skolämnen i gemensamma uppdrag och dela in läsåret i sex tydliga perioder får både elever och lärare en naturlig rytm och balans.','Provider-model context explicitly applied by Oden unit; recurring structure strengthens supported assignment-based code. No extra support code from generic teacher-team provision or arts code from illustrative example.')
add('19983531','rodret_school','I undervisningen arbetar vi ämnesövergripande och tematiskt. Vi skapar, läser, skriver, iakttar, lyssnar, dramatiserar, dansar, sjunger, smakar och fantiserar.','School-specific F–3 Rodret, Skolvägen8 Tungelsta exact fresh official address/grades match. Multiple expressive forms integrated in thematic teaching support arts interpretation; not generic creative label or subject list alone. Not claimed Montessori or sustained inquiry just from thematic wording.','Arts and creative learning','Expressive arts in thematic teaching, F–3','Supported')
add('19983531','rodret_profile','Det är en pedagogisk metod med fokus på att uppleva, reflektera, utvärdera och även inkludera kroppens sinnen samt känslor i de praktiska & teoretiska momenten för att främja kunskap.','Explicit experiential-learning profile applied to both school and preschool; school-specific page independently says it permeates school day, so code restricted schoolF–3, not preschool extrapolation. Sensory/reflection model under Other, no outdoor/alternative named model inferred from trips.','Other stated profile','Experiential learning')
add('20054868','odensala_welcome','Det blir oftast ett annat engagemang när de får hjälpa fiskarna i Lövstaån eller göra ett hotell åt bina, eller när de med hjälp av Kulturskolans dans, sång och teater lär sig om Vikingatiden.','Requires review: Odensala F–6 current official welcome page after old registered404. Concrete environmental/arts-integrated examples, but framed in rector vision with no recurrence, participating years or sustained model. Retain uncertain lead, not firm arts/outdoor/inquiry label. Nearby forest alone insufficient; effect wording not project conclusion.')
add('20137688','kappala_profile','Hösten 2025 startade Käppala skola klasser med fotbollsinriktning, i samarbete med IFK Lidingö fotboll.','Käppala F–9 unit; optional football only. Source explicitly anchors first rollout to2025/26 years4and7, plans new4and7 intake next year and full4–9 in third year. At access2026-10-28 do not infer rollout completed or current all4–9 delivery. Proposed training2mornings/week60–70minutes, not verified timetable. Preserve dated scope caveat and future tense.','Other stated profile','Optional football pathway; phased rollout, dated scope')
add('20253736','tegelhagen_outdoor','Ett av våra fokusområden är utomhuspedagogik som vi arbetar med i alla årskurser. Här lär sig eleverna både genom teori och praktik när de har utedagar och lektioner utomhus.','Tegelhagen F–9, official grades1–9. Explicit all-year outdoor teaching, practical examples include cooking/fire/natural materials; frequency not stated. Source page updated2025-04-16; not verified practice or effects.','Outdoor, nature, or place-based learning','Outdoor pedagogy across all years, F–9')
add('20253736','tegelhagen_about','Digitalisering och utomhuspedagogik är våra tvåprofilområden.','Named unit digitalisation profile with explicit integration of technology and devices for pupils. Other stated profile, not quality or automatic innovative/inquiry pedagogy; outdoor category separately sourced. Ordinary device possession alone would be insufficient.','Other stated profile','Stated digitalisation profile')
